#include "soft_renderer.hpp"
#include <cassert>
#include <cstdio>
using namespace soft;
static void draw(Renderer& r,const Texture& t,float far=0.25f){ScreenState s;s.zTest=true;s.zWrite=false;s.blend=3;s.alphaRef=1;s.perspectiveColor=true;s.addressU=s.addressV=3;ScreenVertex a[3]={{0,0,.25f,0,0,25,70,110,255},{320,0,far,1,0,25,70,110,255},{0,240,far,0,1,25,70,110,255}};ScreenVertex b[3]={a[1],{320,240,far,1,1,25,70,110,255},a[2]};r.screenTriangle(a,&t,s);r.screenTriangle(b,&t,s);}
int main(){Texture t;t.width=t.height=1;t.pixels={65535};t.alpha={255};t.decodedOpaque=t.decodedUniform=true;unsigned cases=0;
 for(unsigned scale:{1u,2u,3u})for(bool fast:{false,true}){Renderer r;r.renderScale(scale);r.effectSpansEnabled(fast);r.blackAddEnabled(fast);r.clear(rgb(32,48,64));unsigned w=scale==1?320:scale==2?160:240,h=w*3/4;auto& z=const_cast<std::vector<float>&>(r.depth());for(unsigned y=0;y<h;++y)for(unsigned x=0;x<w/2;++x)z[y*320+x]=(x+y)%3?.5f:0.f;auto depth=z;auto before=r.pixels();assert(r.beginRain());draw(r,t);draw(r,t);r.endRain();assert(r.depth()==depth);auto image=r.pixels();unsigned changed=0;for(unsigned y=0;y<240;++y)for(unsigned x=0;x<320;++x){unsigned wx=x*w/320,wy=y*h/240;if(depth[wy*320+wx]>=.25f)assert(image[y*320+x]==before[y*320+x]);changed+=image[y*320+x]!=before[y*320+x];}assert(changed>1000&&r.stats().rainPasses==1&&r.stats().rainCompositePixels>0);assert(r.beginRain());draw(r,t,.05f);r.endRain();assert(r.depth()==depth);++cases;
  assert(r.beginRain());draw(r,t);r.clear(rgb(1,2,3));assert(!r.rainActive());assert(r.pixels()[0]==rgb(1,2,3));assert(r.beginRain());draw(r,t);auto newDepth=r.depth();r.beginHud(640);assert(!r.rainActive());r.clear(0);assert(r.beginRain());draw(r,t);r.beginUi(true);assert(!r.rainActive());r.clear(0);assert(r.beginRain());ScreenState bad;bad.blend=1;ScreenVertex v[3]={{0,0,1,0,0,1,2,3,255},{10,0,1,0,0,1,2,3,255},{0,10,1,0,0,1,2,3,255}};r.screenTriangle(v,nullptr,bad);assert(!r.rainActive()&&r.stats().rainFallbacks==1);
 }
 Renderer r;r.renderScale(4);assert(!r.beginRain());r.renderScale(3);r.clear(0);assert(r.beginRain());draw(r,t);r.pixels();assert(!r.rainActive());puts("PASS rain layer: 6 world/FAST modes, conservative occlusion, full depth unchanged, sloping triangles, RGB accumulation, clear/HUD/native UI/resolve and fallback");}
